BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=public,extensions,pg_temp;
SELECT no_plan();
INSERT INTO auth.users(id,email,raw_user_meta_data) VALUES('91100000-0000-4000-8000-000000000010','audit-signup@example.invalid','{"full_name":"Synthetic fixture","avatar_url":"https://unreviewed.invalid/photo.jpg"}');
SELECT ok((SELECT avatar_url IS NULL FROM public.profiles WHERE id='91100000-0000-4000-8000-000000000010'),'signup metadata cannot import unreviewed external avatars');
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
SELECT is((SELECT count(*) FROM public.claim_post_embedding_jobs(8)),0::bigint,'embedding claim excludes authors without explicit AI permission');
SELECT set_config('request.jwt.claims','{}',true);
SELECT lives_ok($$SELECT moderation_private.check_text('A used textbook in good condition')$$,'ordinary marketplace text allowed');
SELECT throws_ok($$SELECT moderation_private.check_text('I will rape you')$$,'22023','content_not_allowed','threat rejected');
SELECT throws_ok($$SELECT moderation_private.check_text('未成年裸照')$$,'22023','content_not_allowed','Chinese sexual exploitation rejected');
SELECT throws_ok($$SELECT moderation_private.check_text('https://bit.ly/scam')$$,'22023','content_not_allowed','obfuscated link rejected');
SELECT throws_ok($$SELECT moderation_private.check_text(repeat('x',20001))$$,'22023','content_too_long','oversized content rejected');
SELECT ok(NOT has_table_privilege('authenticated','public.moderated_media','INSERT'),'users cannot forge media approvals');
SELECT ok(NOT has_table_privilege('anon','public.ai_processing_consents','SELECT'),'AI permissions are not public');
SELECT ok(NOT has_function_privilege('anon','public.moderation_queue(integer)','EXECUTE'),'anonymous report access denied');
INSERT INTO public.posts(id,user_id,school_id,type,title,description,status)
 SELECT '91100000-0000-4000-8000-000000000001',id,school_id,'forum','Safety fixture','Ordinary text','active'
 FROM public.profiles WHERE id='00000000-0000-0000-0000-000000000001';
SELECT throws_ok($$UPDATE public.posts SET description='kill yourself' WHERE id='91100000-0000-4000-8000-000000000001'$$,'22023','content_not_allowed','direct update cannot bypass text gate');
SELECT throws_ok($$INSERT INTO public.post_images(post_id,url,bucket,object_path) VALUES('91100000-0000-4000-8000-000000000001','https://evil.invalid/photo.jpg','post-images','unreviewed.jpg')$$,'22023','media_review_required','direct media reference cannot bypass review');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-0000-0000-000000000002"}',true);
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT * FROM public.moderation_report_media('user','91100000-0000-4000-8000-000000000002')$$,'42501','moderation_access_denied','ordinary user cannot discover reported media');
SELECT throws_ok($$SELECT * FROM public.moderation_queue(10)$$,'42501','moderation_access_denied','ordinary user cannot read confidential reports');
SELECT is(public.can_upload_moderated_media('avatars','00000000-0000-0000-0000-000000000002/new.jpg'),false,'missing AI consent denies upload');
SELECT is(public.set_my_ai_consent(true),true,'explicit AI permission stored');
SELECT is(public.can_upload_moderated_media('avatars','00000000-0000-0000-0000-000000000002/new.jpg'),true,'owned avatar permitted after consent');
SELECT is(public.can_upload_moderated_media('avatars','00000000-0000-0000-0000-000000000001/new.jpg'),false,'other account media denied');
SELECT throws_like($$INSERT INTO storage.objects(bucket_id,name) VALUES('avatars','00000000-0000-0000-0000-000000000002/new.jpg')$$,'%row-level security%','raw Storage upload denied even with consent');
SELECT is(public.set_my_ai_consent(false),true,'AI permission can be withdrawn');
SELECT is(public.can_upload_moderated_media('avatars','00000000-0000-0000-0000-000000000002/new.jpg'),false,'withdrawal immediately blocks new transfers');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','',true);
SELECT set_config('request.jwt.claims','{}',true);
INSERT INTO public.content_studio_roles(user_id,role) VALUES('00000000-0000-0000-0000-000000000001','admin') ON CONFLICT(user_id) DO UPDATE SET role='admin';
INSERT INTO public.user_reports(id,reporter_id,reported_user_id,reason,details)
 VALUES('91100000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000002','harassment','Synthetic audit fixture');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-0000-0000-000000000001"}',true);
SET LOCAL ROLE authenticated;
SELECT ok(EXISTS(SELECT 1 FROM public.moderation_queue(200) WHERE id='91100000-0000-4000-8000-000000000002'),'administrator can review user reports');
SELECT throws_ok($$SELECT public.moderation_resolve('user','91100000-0000-4000-8000-000000000002',NULL,'Valid review note')$$,'22023','invalid_moderation_action','null action fails closed');
SELECT is(public.moderation_resolve('user','91100000-0000-4000-8000-000000000002','suspend','Synthetic safety test'),true,'administrator can suspend reported user');
RESET ROLE;
SELECT is((SELECT count(*) FROM moderation_private.audit_log WHERE report_id='91100000-0000-4000-8000-000000000002'),1::bigint,'action audit persisted atomically');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-0000-0000-000000000002"}',true);
SET LOCAL ROLE authenticated;
SELECT throws_ok($$UPDATE public.profiles SET bio='another post' WHERE id='00000000-0000-0000-0000-000000000002'$$,'42501','account_restricted','existing token cannot publish while suspended');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-0000-0000-000000000001"}',true);
SET LOCAL ROLE authenticated;
SELECT is(public.moderation_restore_user('00000000-0000-0000-0000-000000000002','Appeal reviewed and accepted'),true,'administrator can restore after appeal');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','',true);
SELECT set_config('request.jwt.claims','{}',true);
UPDATE auth.users SET raw_user_meta_data='{"original_email":"synthetic@example.invalid","name":"Sensitive Name"}'::jsonb WHERE id='00000000-0000-0000-0000-000000000002';
UPDATE public.profiles SET phone='synthetic-phone',wechat_id='synthetic-contact',bio='Private bio' WHERE id='00000000-0000-0000-0000-000000000002';
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-0000-0000-000000000002"}',true);
SET LOCAL ROLE authenticated;
SELECT is(public.deactivate_my_account(),true,'account deletion completes');
RESET ROLE;
SELECT ok((SELECT raw_user_meta_data - 'deactivated_at'='{}'::jsonb FROM auth.users WHERE id='00000000-0000-0000-0000-000000000002'),'deletion erases all original identity metadata');
SELECT ok((SELECT phone IS NULL AND wechat_id IS NULL AND cover_image_url IS NULL FROM public.profiles WHERE id='00000000-0000-0000-0000-000000000002'),'deletion erases profile contact data');
SELECT is((SELECT count(*) FROM auth.identities WHERE user_id='00000000-0000-0000-0000-000000000002'),0::bigint,'sign-in identities removed');
SELECT * FROM finish();
ROLLBACK;
